CREATE TABLE IF NOT EXISTS settings (`key` varchar(100) PRIMARY KEY, `value` longtext NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id int unsigned AUTO_INCREMENT PRIMARY KEY, name varchar(100) NOT NULL, email varchar(190) NOT NULL UNIQUE, password varchar(255) NOT NULL, role enum('admin','editor','user') NOT NULL DEFAULT 'user', created_at datetime NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS content (id int unsigned AUTO_INCREMENT PRIMARY KEY, type enum('page','post','product') NOT NULL, status enum('draft','published') NOT NULL DEFAULT 'draft', title varchar(255) NOT NULL, slug varchar(190) NOT NULL, body longtext NOT NULL, excerpt text NULL, image varchar(255) NULL, template varchar(100) NOT NULL DEFAULT 'default', language varchar(10) NOT NULL DEFAULT 'ru', translation_group varchar(64) NOT NULL, category_id int unsigned NULL, author_id int unsigned NOT NULL, seo_title varchar(255) NULL, seo_description varchar(320) NULL, review_enabled tinyint(1) NOT NULL DEFAULT 0, review_text text NULL, comments_enabled tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, updated_at datetime NOT NULL, UNIQUE KEY type_slug_lang(type,slug,language), KEY category_id(category_id), KEY translation_group(translation_group)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (id int unsigned AUTO_INCREMENT PRIMARY KEY, name varchar(120) NOT NULL, slug varchar(120) NOT NULL UNIQUE, description text NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comments (id int unsigned AUTO_INCREMENT PRIMARY KEY, content_id int unsigned NOT NULL, name varchar(120) NOT NULL, email varchar(190) NOT NULL, body text NOT NULL, status enum('pending','approved','spam') NOT NULL DEFAULT 'pending', created_at datetime NOT NULL, KEY content_id(content_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS menus (id int unsigned AUTO_INCREMENT PRIMARY KEY, name varchar(100) NOT NULL, location varchar(50) NOT NULL DEFAULT 'header') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS menu_items (id int unsigned AUTO_INCREMENT PRIMARY KEY, menu_id int unsigned NOT NULL, parent_id int unsigned NULL, type varchar(20) NOT NULL DEFAULT 'custom', ref_id int unsigned NULL, label varchar(100) NOT NULL, url varchar(255) NOT NULL, target tinyint(1) NOT NULL DEFAULT 0, sort_order int NOT NULL DEFAULT 0, KEY menu_id(menu_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_buttons (id int unsigned AUTO_INCREMENT PRIMARY KEY, name varchar(100) NOT NULL, label varchar(100) NOT NULL, url varchar(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS button_slots (id int unsigned AUTO_INCREMENT PRIMARY KEY, slot varchar(60) NOT NULL, button_id int unsigned NOT NULL, label varchar(100) NOT NULL, sort_order int NOT NULL DEFAULT 0, KEY slot(slot)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id int unsigned AUTO_INCREMENT PRIMARY KEY, kind enum('service','shop') NOT NULL, product_id int unsigned NULL, customer_name varchar(120) NOT NULL, email varchar(190) NOT NULL, phone varchar(50) NULL, message text NULL, status enum('new','processing','done','cancelled') NOT NULL DEFAULT 'new', created_at datetime NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_log (id int unsigned AUTO_INCREMENT PRIMARY KEY, user_id int unsigned NOT NULL DEFAULT 0, action varchar(100) NOT NULL, ip varchar(45) NOT NULL DEFAULT '', created_at datetime NOT NULL, KEY user_id(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
